package com.example;

import java.util.List;
import java.util.Objects;
import java.util.Optional;

public class OrderService {

    private final OrderRepository repository;
    private final AuditLog auditLog;

    public OrderService(OrderRepository repository, AuditLog auditLog) {
        this.repository = Objects.requireNonNull(repository);
        this.auditLog = Objects.requireNonNull(auditLog);
    }

    public double total(List<Order> orders) {
        double sum = 0;
        for (Order order : orders) {
            sum += order.amount();
        }
        return sum;
    }

    public Optional<Order> findOrder(String id) {
        return Optional.ofNullable(repository.find(id)).map(Order::normalise);
    }

    public Optional<Order> latest() {
        return Optional.ofNullable(repository.latest()).map(Order::normalise);
    }
}
